# 拉取 Live2D Cubism Core
#
# live2dcubismcore.min.js 是 Live2D 株式会社的专有软件，本仓库不直接分发。
# 这个脚本从官方 CDN 下载，放到 WebView 前端目录里。
#
# 个人 / 小微企业使用是免费且免签约的；商用前请阅读：
#   https://www.live2d.com/en/sdk/license/

$ErrorActionPreference = 'Stop'

$dest = Join-Path $PSScriptRoot '..\source\webassets\live2dcubismcore.min.js'
$dest = [IO.Path]::GetFullPath($dest)

$urls = @(
    'https://cubism.live2d.com/sdk-web/cubismcore/live2dcubismcore.min.js',
    'https://cdn.jsdelivr.net/gh/Live2D/CubismWebFramework@develop/Core/live2dcubismcore.min.js'
)

if (Test-Path -LiteralPath $dest) {
    $size = (Get-Item -LiteralPath $dest).Length
    Write-Host "已存在（$([math]::Round($size/1KB)) KB）：$dest" -ForegroundColor Green
    Write-Host "要重新下载请先删掉它。"
    exit 0
}

Write-Host "下载 Live2D Cubism Core …"
$ok = $false
foreach ($u in $urls) {
    try {
        Invoke-WebRequest $u -OutFile $dest -UseBasicParsing -TimeoutSec 60
        $size = (Get-Item -LiteralPath $dest).Length
        if ($size -lt 50KB) { throw "文件太小（$size 字节），可能不是正确内容" }
        Write-Host "  ✅ 已下载 $([math]::Round($size/1KB)) KB" -ForegroundColor Green
        Write-Host "     来源：$u"
        $ok = $true
        break
    } catch {
        Write-Host "  ✗ $u" -ForegroundColor DarkGray
        Write-Host "    $($_.Exception.Message)" -ForegroundColor DarkGray
        if (Test-Path -LiteralPath $dest) { Remove-Item -LiteralPath $dest -Force }
    }
}

if (-not $ok) {
    Write-Host ""
    Write-Host "自动下载失败。请手动获取：" -ForegroundColor Yellow
    Write-Host "  1. 打开 https://www.live2d.com/en/sdk/download/web/"
    Write-Host "  2. 下载 Cubism SDK for Web"
    Write-Host "  3. 从 Core/ 目录里取出 live2dcubismcore.min.js"
    Write-Host "  4. 放到：$dest"
    exit 1
}

Write-Host ""
Write-Host "接下来：" -ForegroundColor Cyan
Write-Host "  `$env:WHALE_KEYSTORE_PASSWORD = '你的口令'"
Write-Host "  .\build.ps1"
=== index.html ===
<!DOCTYPE html>
<html lang="zh">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
<title>鲸鱼娘 Live2D</title>
<script src="live2dcubismcore.min.js"></script>
<script src="pixi.min.js"></script>
<script src="cubism4.min.js"></script>
<style>
  html,body{margin:0;padding:0;width:100%;height:100%;overflow:hidden;background:transparent}
  canvas{display:block}
</style>
</head>
<body>
<script>
(function () {
  var MODEL = null, APP = null, ready = false;
  var frozen = false;

  function boot() {
    APP = new PIXI.Application({
      width: window.innerWidth,
      height: window.innerHeight,
      backgroundAlpha: 0,
      antialias: true,
      resolution: Math.min(3, window.devicePixelRatio || 1),
      autoDensity: true,
    });
    document.body.appendChild(APP.view);

    PIXI.live2d.Live2DModel.from('model/whalegirl.model3.json', { autoInteract: false })
      .then(function (m) {
        MODEL = m;
        window.__model = m;
        APP.stage.addChild(m);
        fit();
        m.internalModel.motionManager.groups.idle = 'Idle';
        // 自动眨眼交给 pixi-live2d-display（model3.json 里已声明 EyeBlink 组）
        m.motion('Idle');
        // 每帧把嘴钉在基线上，否则会被动作用参数拉回 0 而消失
        APP.ticker.add(function () { applyMouth(); });
        ready = true;
        window.__ready = true;
        window.Android && window.Android.onReady && window.Android.onReady();
      })
      .catch(function (e) {
        window.__err = String(e);
        window.Android && window.Android.onError && window.Android.onError(String(e));
      });
  }

  function fit() {
    if (!MODEL) return;
    var w = window.innerWidth, h = window.innerHeight;
    if (w < 8 || h < 8) return;              // 布局还没完成，跳过
    APP.renderer.resize(w, h);
    // 注意：pixi 的 MODEL.width/height 已经含了 scale，直接拿会重复相乘。
    // 先把缩放归 1 量出原始尺寸，再算适配。
    MODEL.scale.set(1);
    var nw = MODEL.width, nh = MODEL.height;
    if (!nw || !nh) return;
    var s = Math.min(w / nw, h / nh) * 0.98;
    MODEL.scale.set(s);
    MODEL.x = (w - nw * s) / 2;
    MODEL.y = (h - nh * s) / 2;
  }
  window.addEventListener('resize', fit);
  window.addEventListener('orientationchange', function () { setTimeout(fit, 120); });
  // WebView 首次布局完成得晚，光靠 resize 事件不够，前两秒多补几次
  [50, 150, 300, 600, 1000, 1800].forEach(function (ms) { setTimeout(fit, ms); });

  function core() { return MODEL && MODEL.internalModel.coreModel; }
  function set(id, v) { var c = core(); if (c) { try { c.setParameterValueById(id, v); } catch (e) {} } }
  // pixi-live2d-display 的 MotionManager 在没有动作播放时，每帧都会 loadParameters()
  // 把参数恢复到"上一次 saveParameters 的快照"。所以手动设完必须快照一次，
  // 否则值活不过一帧（这就是之前"设了没反应"的原因）。
  function lock() { var c = core(); if (c && c.saveParameters) { try { c.saveParameters(); } catch (e) {} } }

  // psd2live 约定：PSD 里的 mouth 是"最大张口"原图，ParamMouthOpenY 从张口向中线压缩闭口。
  // 我们这张原画本身是微笑小嘴（并不是张口），所以参数为 0 时会被压成一条线、看起来"没有嘴"。
  // 这里给一个基线，让嘴保持原画的形状；动作只在这个基线附近微调。
  var mouthBase = 1.0;
  var mouthScale = 1.0;
  function applyMouth() { set('ParamMouthOpenY', Math.max(0, Math.min(1.2, mouthBase * mouthScale))); }

  // ---- 给 Android 调用的接口 ----
  window.petReady = function () { return !!ready; };
  /** 闭眼程度 0..1（1=全睁）。用于验证眼皮变形。 */
  window.petBlink = function (v) {
    frozen = true;
    set('ParamEyeLOpen', v); set('ParamEyeROpen', v); lock();
  };
  window.petPlay = function (group) { if (MODEL) { try { MODEL.motion(group); } catch (e) {} } };
  window.petFreeze = function (v) { frozen = !!v; };
  window.petSet = function (id, v) { frozen = true; set(id, v); lock(); };
  window.petGaze = function (x, y) { frozen = true; set('ParamEyeBallX', x); set('ParamEyeBallY', y || 0); lock(); };
  window.petThaw = function () {
    frozen = false;
    ['ParamAngleX','ParamAngleY','ParamAngleZ','ParamEyeBallX','ParamEyeBallY',
     'ParamBodyAngleX','ParamBrowLY','ParamBrowRY'].forEach(function (p) { set(p, 0); });
    lock();
  };
  // 动作预设：用标准参数组合出表情/姿态
  window.petAction = function (name) {
    frozen = true;
    mouthScale = 1.0;
    var P = { AngleX:0, AngleY:0, AngleZ:0, EyeBallX:0, EyeBallY:0,
              BrowL:0, BrowR:0, MouthForm:0, Breath:1, BodyX:0 };
    switch (name) {
      case 'curious':   P.AngleZ = -22; P.AngleX = -14; P.AngleY = -8;  P.BrowL = 1; P.BrowR = 1;
                        P.EyeBallX = -0.5; P.EyeBallY = -0.7; mouthScale = 0.92; break;
      case 'happy':     P.AngleZ = 14;  P.AngleY = -10; P.MouthForm = 1; P.Breath = 1.8; P.BodyX = 6; break;
      case 'sleepy':    P.AngleY = 18;  P.AngleZ = -10; P.EyeBallY = 0.6; P.Breath = 2.2; mouthScale = 0.66; break;
      case 'surprised': P.AngleY = -18; P.AngleZ = 8;   P.BrowL = 0.8; P.BrowR = 0.8;
                        P.Breath = 1.5; mouthScale = 1.15; break;
      default: break;   // idle
    }
    set('ParamAngleX', P.AngleX);   set('ParamAngleY', P.AngleY);   set('ParamAngleZ', P.AngleZ);
    set('ParamEyeBallX', P.EyeBallX); set('ParamEyeBallY', P.EyeBallY);
    set('ParamBrowLY', P.BrowL);    set('ParamBrowRY', P.BrowR);
    set('ParamMouthForm', P.MouthForm);
    set('ParamBodyAngleX', P.BodyX);
    applyMouth();
    lock();
    if (name === 'idle') { frozen = false; window.petThaw(); }
  };

  if (window.PIXI && PIXI.live2d) boot();
  else {
    // 脚本可能还没就绪，退一帧再试
    setTimeout(function () { if (window.PIXI && PIXI.live2d) boot(); else window.__err = 'PIXI/live2d 未加载'; }, 200);
  }
})();
</script>
</body>
</html>

