  if(mode==='a'){ holder.mask=mask; mask.isMask=true; }
  if(mode==='b'){ holder.mask=mask; mask.renderable=false; }
  if(mode==='c'){ mask.isMask=true; app.stage.mask=mask; }
  return app;
}
mk('a','a'); mk('b','b'); mk('c','c');
</script></body></html>
EOF
