package com.vtuber.ai

import android.util.Log
import okhttp3.Call
import okhttp3.Callback
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import okhttp3.Response
import org.json.JSONArray
import org.json.JSONObject
import java.io.IOException
import java.util.concurrent.TimeUnit

class ChatClient {

    interface Listener {
        fun onReply(text: String)
        fun onFailure(message: String)
    }

    private val client = OkHttpClient.Builder()
        .connectTimeout(20, TimeUnit.SECONDS)
        .readTimeout(60, TimeUnit.SECONDS)
        .build()

    private val json = "application/json; charset=utf-8".toMediaType()

    fun send(prefs: Prefs, userMessage: String, listener: Listener) {
        val messages = JSONArray()
        messages.put(JSONObject().put("role", "system").put("content", prefs.characterRole))
        val history = prefs.history()
        for (index in 0 until history.length()) {
            val turn = history.optJSONObject(index) ?: continue
            messages.put(turn)
        }
        messages.put(JSONObject().put("role", "user").put("content", userMessage))

        val payload = JSONObject()
            .put("model", prefs.modelName)
            .put("messages", messages)
            .put("temperature", 0.8)
            .put("max_tokens", 400)
            .toString()

        val request = Request.Builder()
            .url(prefs.modelUrl)
            .post(payload.toRequestBody(json))
            .header("Authorization", "Bearer ${prefs.apiKey}")
            .header("Content-Type", "application/json")
            .build()

        client.newCall(request).enqueue(object : Callback {
            override fun onFailure(call: Call, e: IOException) {
                Log.e(TAG, "request failed", e)
                listener.onFailure(e.message ?: "сеть недоступна")
            }

            override fun onResponse(call: Call, response: Response) {
                response.use {
                    val body = it.body?.string().orEmpty()
                    if (!it.isSuccessful) {
                        listener.onFailure("HTTP ${it.code}")
                        return
                    }
                    val content = try {
                        JSONObject(body)
                            .getJSONArray("choices")
                            .getJSONObject(0)
                            .getJSONObject("message")
                            .getString("content")
                    } catch (e: Exception) {
                        Log.e(TAG, "bad response", e)
                        null
                    }
                    if (content.isNullOrBlank()) {
                        listener.onFailure("пустой ответ модели")
                    } else {
                        listener.onReply(content.trim())
                    }
                }
            }
        })
    }

    companion object {
        private const val TAG = "ChatClient"
    }
}

package com.vtuber.ai

import android.content.Context
import android.media.AudioAttributes
import android.media.MediaPlayer
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.speech.tts.TextToSpeech
import android.speech.tts.UtteranceProgressListener
import android.util.Log
import java.io.File
import java.io.RandomAccessFile
import java.util.Locale
import kotlin.math.abs
import kotlin.math.min
import kotlin.math.sqrt
import kotlin.concurrent.thread

class SpeechPlayer(private val context: Context) {

    interface Listener {
        fun onSpeechStart()
        fun onLevel(level: Float)
        fun onSpeechDone()
    }

    private val handler = Handler(Looper.getMainLooper())
    private var tts: TextToSpeech? = null
    private var voiceReady = false
    private var player: MediaPlayer? = null
    private var levelTask: Runnable? = null
    private var watchdog: Runnable? = null
    private var pendingListener: Listener? = null
    private var currentText: String = ""

    @Volatile
    private var synthesized = false

    fun init(onFailure: (String) -> Unit) {
        if (tts != null) return
        tts = TextToSpeech(context.applicationContext) { status ->
            voiceReady = status == TextToSpeech.SUCCESS
            if (voiceReady) {
                val engine = tts
                engine?.language = Locale("ru", "RU")
                engine?.setSpeechRate(1.02f)
                engine?.setPitch(1.08f)
                engine?.setOnUtteranceProgressListener(object : UtteranceProgressListener() {
                    override fun onStart(utteranceId: String?) {
                        if (utteranceId == FILE_ID) synthesized = true
                    }

                    override fun onDone(utteranceId: String?) {
                        if (utteranceId == FILE_ID) {
                            handler.post { playFile() }
                        } else if (utteranceId == SPEECH_ID) {
                            finish()
                        }
                    }

                    @Deprecated("Deprecated in Java")
                    override fun onError(utteranceId: String?) {
                        if (utteranceId == FILE_ID) {
                            handler.post { speakDirectly() }
                        }
                    }

                    override fun onError(utteranceId: String?, errorCode: Int) {
                        if (utteranceId == FILE_ID) {
                            handler.post { speakDirectly() }
                        }
                    }
                })
            } else {
                onFailure("Синтез речи недоступен на этом устройстве")
            }
        }
    }

    fun speak(text: String, listener: Listener) {
        val engine = tts
        if (text.isBlank() || engine == null || !voiceReady) return
        stop()
        currentText = text
        pendingListener = listener
        synthesized = false
        listener.onSpeechStart()
        val file = File(context.cacheDir, "reply.wav")
        file.delete()
        val params = Bundle().apply {
            putString(TextToSpeech.Engine.KEY_PARAM_UTTERANCE_ID, FILE_ID)
        }
        val result = try {
            engine.synthesizeToFile(text, params, file, FILE_ID)
        } catch (e: Exception) {
            Log.e(TAG, "synthesizeToFile failed", e)
            TextToSpeech.ERROR
        }
        if (result != TextToSpeech.SUCCESS) {
            speakDirectly()
            return
        }
        watchdog = Runnable {
            if (!synthesized) {
                Log.w(TAG, "synthesis timed out, falling back to direct speak")
                speakDirectly()
            }
        }.also { handler.postDelayed(it, WATCHDOG_MS) }
    }

    private fun speakDirectly() {
        cancelWatchdog()
        val engine = tts ?: return
        val id = SPEECH_ID + System.currentTimeMillis()
        try {
            engine.speak(currentText, TextToSpeech.QUEUE_FLUSH, null, id)
        } catch (e: Exception) {
            Log.e(TAG, "speak failed", e)
            finish()
        }
    }

    private fun playFile() {
        cancelWatchdog()
        val file = File(context.cacheDir, "reply.wav")
        if (!file.exists() || file.length() < 64) {
            speakDirectly()
            return
        }
        val envelope = thread(name = "tts-envelope") { analyze(file) }
        try {
            player?.release()
            player = MediaPlayer().apply {
                setAudioAttributes(
                    AudioAttributes.Builder()
                        .setUsage(AudioAttributes.USAGE_MEDIA)
                        .setContentType(AudioAttributes.CONTENT_TYPE_SPEECH)
                        .build()
                )
                setDataSource(file.absolutePath)
                setOnCompletionListener { finish() }
                setOnErrorListener { _, _, _ ->
                    finish()
                    true
                }
                prepare()
                start()
            }
        } catch (e: Exception) {
            Log.e(TAG, "playback failed", e)
            speakDirectly()
            return
        }
        val levels = arrayOfNulls<FloatArray>(1)
        envelope.start()
        val task = object : Runnable {
            override fun run() {
                val current = player ?: return
                if (!current.isPlaying) return
                val position = current.currentPosition
                val data = levels[0] ?: run {
                    envelope.join()
                    levels[0]
                }
                if (data == null || data.isEmpty()) {
                    pendingListener?.onLevel(0.35f)
                } else {
                    val index = (position / FRAME_MS).toInt()
                    pendingListener?.onLevel(data[index.coerceIn(0, data.size - 1)])
                }
                handler.postDelayed(this, FRAME_MS)
            }
        }
        levelTask = task
        handler.postDelayed(task, FRAME_MS)
        handler.postDelayed({
            envelope.join()
            levels[0] = runCatching { envelope.get() }.getOrNull()
        }, 100)
    }

    private fun analyze(file: File) {
        try {
            RandomAccessFile(file, "r").use { raf ->
                val header = ByteArray(12)
                raf.readFully(header)
                var rate = 22050
                var channels = 1
                var bits = 16
                var dataOffset = 44L
                var dataSize = 0L
                while (raf.filePointer < raf.length()) {
                    val chunk = ByteArray(8)
                    raf.readFully(chunk)
                    val id = String(chunk, 0, 4, Charsets.US_ASCII)
                    val size = ((chunk[4].toLong() and 0xFF) or
                        (chunk[5].toLong() shl 8) or
                        (chunk[6].toLong() shl 16) or
                        (chunk[7].toLong() shl 24))
                    if (id == "fmt ") {
                        val fmt = ByteArray(size.toInt().coerceAtMost(16))
                        raf.readFully(fmt)
                        channels = ((fmt[2].toInt() and 0xFF) or (fmt[3].toInt() shl 8)).coerceAtLeast(1)
                        rate = ((fmt[4].toInt() and 0xFF) or (fmt[5].toInt() shl 8) or
                            (fmt[6].toInt() shl 16) or (fmt[7].toInt() shl 24)).coerceAtLeast(8000)
                        bits = ((fmt[14].toInt() and 0xFF) or (fmt[15].toInt() shl 8)).coerceAtLeast(8)
                    } else if (id == "data") {
                        dataOffset = raf.filePointer
                        dataSize = size
                        break
                    } else {
                        raf.seek(raf.filePointer + size + (size and 1L))
                    }
                }
                val bytesPerSample = (bits / 8).coerceAtLeast(1)
                val frameSamples = (rate / 1000 * FRAME_MS).coerceAtLeast(1)
                val bytesPerFrame = frameSamples * channels * bytesPerSample
                val frames = (dataSize / bytesPerFrame).toInt().coerceAtLeast(1)
                val levels = FloatArray(frames)
                val buffer = ByteArray(bytesPerFrame.coerceAtMost(1 shl 16))
                var peak = 0f
                for (index in 0 until frames) {
                    val read = raf.read(buffer, 0, min(buffer.size, bytesPerFrame))
                    if (read <= 0) break
                    var sum = 0.0
                    var samples = 0
                    var offset = 0
                    while (offset + 1 < read) {
                        val sample = ((buffer[offset + 1].toInt() shl 8) or (buffer[offset].toInt() and 0xFF)) / 32768.0
                        sum += sample * sample
                        samples++
                        offset += 2
                    }
                    val rms = if (samples == 0) 0f else sqrt(sum / samples).toFloat()
                    levels[index] = rms
                    if (rms > peak) peak = rms
                }
                if (peak > 0.001f) {
                    for (index in levels.indices) {
                        val normalized = (levels[index] / peak).coerceIn(0f, 1f)
                        levels[index] = (0.18f + 0.82f * abs(normalized)).coerceIn(0f, 1f)
                    }
                }
                file.writeBytes(levels.toJson())
            }
        } catch (e: Exception) {
            Log.e(TAG, "envelope analysis failed", e)
        }
    }

    private fun FloatArray.toJson(): ByteArray = joinToString(",") { it.toString() }.toByteArray()

    private fun stopPlayback() {
        levelTask?.let { handler.removeCallbacks(it) }
        levelTask = null
        player?.let {
            runCatching { it.stop() }
            it.release()
        }
        player = null
    }

    fun stop() {
        cancelWatchdog()
        stopPlayback()
        tts?.stop()
        pendingListener?.let {
            it.onLevel(0f)
            it.onSpeechDone()
        }
        pendingListener = null
    }

    fun shutdown() {
        stop()
        tts?.shutdown()
        tts = null
    }

    private fun finish() {
        cancelWatchdog()
        stopPlayback()
        val listener = pendingListener
        pendingListener = null
        listener?.onLevel(0f)
        listener?.onSpeechDone()
    }

    private fun cancelWatchdog() {
        watchdog?.let { handler.removeCallbacks(it) }
        watchdog = null
    }

    companion object {
        private const val TAG = "SpeechPlayer"
        private const val FILE_ID = "vtuber-file"
        private const val SPEECH_ID = "vtuber-direct"
        private const val FRAME_MS = 45L
        private const val WATCHDOG_MS = 3500L
    }
}

