package com.vtuber.ai

import android.Manifest
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.os.Bundle
import android.speech.RecognitionListener
import android.speech.RecognizerIntent
import android.speech.SpeechRecognizer
import android.util.Log
import androidx.core.content.ContextCompat

object VoiceChatManager {

    interface Listener {
        fun onMood(mood: String)
        fun onCaption(text: String)
        fun onLevel(level: Float)
        fun onHeard(text: String)
        fun onError(message: String)
    }

    private val TAG = "VoiceChat"
    private var recognizer: SpeechRecognizer? = null
    private var speech: SpeechPlayer? = null
    private val chat = ChatClient()

    @Volatile
    private var listening = false

    @Volatile
    private var speaking = false

    var listener: Listener? = null

    fun hasPermission(context: Context): Boolean =
        ContextCompat.checkSelfPermission(context, Manifest.permission.RECORD_AUDIO) ==
            PackageManager.PERMISSION_GRANTED

    fun isListening(): Boolean = listening

    fun isSpeaking(): Boolean = speaking

    fun init(context: Context) {
        if (speech == null) {
            speech = SpeechPlayer(context.applicationContext).apply {
                init { message -> listener?.onError(message) }
            }
        }
    }

    fun toggle(context: Context) {
        if (listening || speaking) {
            stop()
        } else {
            start(context)
        }
    }

    fun start(context: Context) {
        if (listening || speaking) return
        if (!hasPermission(context)) {
            listener?.onError("Нет доступа к микрофону")
            return
        }
        val app = context.applicationContext
        init(app)
        val intent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
            putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)
            putExtra(RecognizerIntent.EXTRA_LANGUAGE, "ru-RU")
            putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS, true)
            putExtra(RecognizerIntent.EXTRA_MAX_RESULTS, 1)
            putExtra(RecognizerIntent.EXTRA_CALLING_PACKAGE, app.packageName)
        }
        if (speech == null) return
        stopSpeech()
        val instance = recognizer ?: SpeechRecognizer.createSpeechRecognizer(app).also {
            recognizer = it
        }
        instance.setRecognitionListener(object : RecognitionListener {
            override fun onReadyForSpeech(params: Bundle?) = Unit

            override fun onBeginningOfSpeech() {
                listener?.onMood("listening")
            }

            override fun onRmsChanged(rmsdB: Float) = Unit

            override fun onBufferReceived(buffer: ByteArray?) = Unit

            override fun onEndOfSpeech() {
                listener?.onMood("thinking")
            }

            override fun onError(error: Int) {
                listening = false
                if (error == SpeechRecognizer.ERROR_NO_MATCH || error == SpeechRecognizer.ERROR_SPEECH_TIMEOUT) {
                    listener?.onMood("idle")
                } else {
                    listener?.onError(errorText(error))
                    listener?.onMood("idle")
                }
            }

            override fun onResults(results: Bundle?) {
                listening = false
                val text = results
                    ?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)
                    ?.firstOrNull()
                    .orEmpty()
                if (text.isBlank()) {
                    listener?.onMood("idle")
                } else {
                    ask(app, text)
                }
            }

            override fun onPartialResults(partialResults: Bundle?) {
                partialResults
                    ?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)
                    ?.firstOrNull()
                    ?.takeIf { it.isNotBlank() }
                    ?.let { listener?.onCaption(it) }
            }

            override fun onEvent(eventType: Int, params: Bundle?) = Unit
        })
        listening = true
        instance.startListening(intent)
    }

    private fun ask(context: Context, text: String) {
        val prefs = Prefs(context)
        listener?.onMood("thinking")
        listener?.onCaption("")
        listener?.onHeard(text)
        chat.send(prefs, text, object : ChatClient.Listener {
            override fun onReply(reply: String) {
                prefs.addTurn("user", text)
                prefs.addTurn("assistant", reply)
                speak(reply)
            }

            override fun onFailure(message: String) {
                Log.e(TAG, "model failure: $message")
                listener?.onError("Модель молчит: $message")
                listener?.onCaption("Не получилось получить ответ")
                listener?.onMood("idle")
            }
        })
    }

    private fun speak(reply: String) {
        val player = speech ?: return
        speaking = true
        player.speak(reply, object : SpeechPlayer.Listener {
            override fun onSpeechStart() {
                listener?.onMood("speaking")
                listener?.onCaption(reply)
            }

            override fun onLevel(level: Float) {
                listener?.onLevel(level)
            }

            override fun onSpeechDone() {
                speaking = false
                listener?.onLevel(0f)
                listener?.onCaption("")
                listener?.onMood("idle")
            }
        })
    }

    fun stop() {
        listening = false
        runCatching { recognizer?.cancel() }
        stopSpeech()
        listener?.onLevel(0f)
        listener?.onMood("idle")
    }

    private fun stopSpeech() {
        speaking = false
        speech?.stop()
    }

    fun destroy() {
        stop()
        runCatching { recognizer?.destroy() }
        recognizer = null
        speech?.shutdown()
        speech = null
    }

    private fun errorText(error: Int): String = when (error) {
        SpeechRecognizer.ERROR_AUDIO -> "Ошибка записи звука"
        SpeechRecognizer.ERROR_CLIENT -> "Ошибка распознавания"
        SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS -> "Нет доступа к микрофону"
        SpeechRecognizer.ERROR_NETWORK -> "Нет сети для распознавания"
        SpeechRecognizer.ERROR_NETWORK_TIMEOUT -> "Сеть не отвечает"
        SpeechRecognizer.ERROR_RECOGNIZER_BUSY -> "Распознаватель занят"
        SpeechRecognizer.ERROR_SERVER -> "Сервер распознавания недоступен"
        else -> "Распознавание не удалось"
    }
}

package com.vtuber.ai

import android.annotation.SuppressLint
import android.content.Context
import android.graphics.Color
import android.util.AttributeSet
import android.util.Log
import android.view.ViewOutlineProvider
import android.webkit.JavascriptInterface
import android.webkit.WebResourceRequest
import android.webkit.WebResourceResponse
import android.webkit.WebView
import android.widget.FrameLayout
import androidx.webkit.WebViewAssetLoader
import androidx.webkit.WebViewClientCompat

class AvatarWebView @JvmOverloads constructor(
    context: Context,
    attrs: AttributeSet? = null
) : FrameLayout(context, attrs) {

    interface Listener {
        fun onModelReady(model: String)
        fun onModelError(message: String)
        fun onAvatarTap(x: Float, y: Float)
    }

    private val webView = WebView(context)
    private val queued = ArrayList<String>()
    private val assetLoader = WebViewAssetLoader.Builder()
        .addPathHandler("/assets/", WebViewAssetLoader.AssetsPathHandler(context))
        .build()
    private var ready = false

    var listener: Listener? = null

    val cornerRadius: Float
        get() = minOf(width, height) * 0.11f

    private val bridge = object {
        @JavascriptInterface
        fun onReady(model: String) {
            post {
                ready = true
                queued.forEach { script -> webView.evaluateJavascript(script, null) }
                queued.clear()
                listener?.onModelReady(model)
            }
        }

        @JavascriptInterface
        fun onError(message: String) {
            post { listener?.onModelError(message) }
        }

        @JavascriptInterface
        fun onTap(x: Float, y: Float) {
            post { listener?.onAvatarTap(x, y) }
        }
    }

    init {
        setBackgroundColor(Color.TRANSPARENT)
        clipChildren = false
        outlineProvider = object : ViewOutlineProvider() {
            override fun getOutline(view: View, outline: android.graphics.Outline) {
                outline.setRoundRect(0, 0, view.width, view.height, cornerRadius)
            }
        }
        clipToOutline = true

        @SuppressLint("SetJavaScriptEnabled")
        webView.apply {
            settings.javaScriptEnabled = true
            settings.domStorageEnabled = true
            settings.mediaPlaybackRequiresUserGesture = false
            setBackgroundColor(Color.TRANSPARENT)
            overScrollMode = OVER_SCROLL_NEVER
            isVerticalScrollBarEnabled = false
            isHorizontalScrollBarEnabled = false
            webViewClient = object : WebViewClientCompat() {
                override fun shouldInterceptRequest(
                    view: WebView,
                    request: WebResourceRequest
                ): WebResourceResponse? = assetLoader.shouldInterceptRequest(request.url)
            }
            addJavascriptInterface(bridge, "VtuberAvatar")
            addView(this, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT))
        }
    }

    fun load(model: String) {
        ready = false
        webView.loadUrl("$BASE_URL/avatar/index.html?model=$model")
    }

    fun mood(mood: String) = call("mood", "'$mood'")

    fun speak(on: Boolean) = call("speak", on.toString())

    fun level(value: Float) = call("level", value.toString())

    fun caption(text: String) = call("caption", quote(text))

    fun status(text: String) = call("status", quote(text))

    fun gaze(x: Float, y: Float) = call("gaze", "$x, $y")

    fun tilt(degrees: Float) = call("tilt", degrees.toString())

    fun pulse() = call("pulse()")

    fun dim(value: Float) = call("dim", value.toString())

    fun switchModel(model: String) = call("model", quote(model))

    fun isModelReady(): Boolean = ready

    private fun call(method: String, args: String) {
        val script = "if (window.vtuberApi) { window.vtuberApi.$method($args); }"
        if (ready) {
            webView.evaluateJavascript(script, null)
        } else {
            queued.add(script)
        }
    }

    private fun quote(text: String): String {
        val escaped = text.replace("\\", "\\\\").replace("'", "\\'").replace("\n", " ")
        return "'$escaped'"
    }

    fun release() {
        queued.clear()
        webView.removeJavascriptInterface("VtuberAvatar")
        webView.destroy()
    }

    companion object {
        private const val TAG = "AvatarWebView"
        private const val BASE_URL = "https://appassets.androidplatform.net"
    }
}

