        (webView.parent as? FrameLayout)?.removeView(webView)
        webView.destroy()
    }

    companion object {
        private const val BASE_URL = "https://appassets.androidplatform.net"
    }
}

package com.vtuber.ai

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.app.Service
import android.content.Intent
import android.content.pm.ServiceInfo
import android.graphics.PixelFormat
import android.os.Build
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.util.Log
import android.view.Gravity
import android.view.LayoutInflater
import android.view.MotionEvent
import android.view.ScaleGestureDetector
import android.view.View
import android.view.WindowManager
import android.widget.TextView
import androidx.core.app.NotificationCompat
import kotlin.math.abs
import kotlin.math.roundToInt

class OverlayService : Service(), AvatarWebView.Listener, VoiceChatManager.Listener {

    private val handler = Handler(Looper.getMainLooper())
    private lateinit var prefs: Prefs
    private lateinit var avatar: AvatarWebView
    private var windowManager: WindowManager? = null
    private var params: WindowManager.LayoutParams? = null
    private var scaleDetector: ScaleGestureDetector? = null

    private var baseWidth = BASE_WIDTH
    private var baseHeight = BASE_HEIGHT
    private var downX = 0
    private var downY = 0
    private var startX = 0
    private var startY = 0
    private var dragging = false
    private var scaling = false
    private var lastTapAt = 0L
    private var privacy = false

    private val hideTask = Runnable { stopSelf() }

    override fun onCreate() {
        super.onCreate()
        prefs = Prefs(this)
        windowManager = getSystemService(WINDOW_SERVICE) as WindowManager
        baseWidth = (BASE_WIDTH * prefs.avatarScale).roundToInt()
        baseHeight = (BASE_HEIGHT * prefs.avatarScale).roundToInt()
        createChannel()
        buildAvatar()
        VoiceChatManager.listener = this
        VoiceChatManager.init(this)
        if (prefs.privacyMode) applyPrivacy(true)
        startForegroundNotification()
        handler.postDelayed(hideTask, AUTO_HIDE_MS)
    }

    private fun buildAvatar() {
        avatar = AvatarWebView(this).apply {
            listener = this@OverlayService
            setOnTouchListener(touchListener)
        }
        val layout = LayoutInflater.from(this).inflate(R.layout.overlay_avatar, null)
        val status = layout.findViewById<TextView>(R.id.overlay_status)
        params = WindowManager.LayoutParams(
            baseWidth,
            baseHeight,
            WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,
            WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or
                WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,
            PixelFormat.TRANSLUCENT
        ).apply {
            gravity = Gravity.TOP or Gravity.START
            if (prefs.overlayX != Int.MIN_VALUE) {
                x = prefs.overlayX
                y = prefs.overlayY
            } else {
                val metrics = resources.displayMetrics
                x = metrics.widthPixels - baseWidth - (16 * metrics.density).roundToInt()
                y = (metrics.heightPixels * 0.45f).roundToInt()
            }
        }
        val container = android.widget.FrameLayout(this).apply {
            addView(
                avatar,
                android.widget.FrameLayout.LayoutParams(
                    android.widget.FrameLayout.LayoutParams.MATCH_PARENT,
                    android.widget.FrameLayout.LayoutParams.MATCH_PARENT
                )
            )
            addView(
                status,
                android.widget.FrameLayout.LayoutParams(
                    android.widget.FrameLayout.LayoutParams.MATCH_PARENT,
                    android.widget.FrameLayout.LayoutParams.WRAP_CONTENT,
                    Gravity.BOTTOM
                )
            )
            background = R.drawable.overlay_background
        }
        scaleDetector = ScaleGestureDetector(this, scaleListener)
        avatar.load(prefs.avatarModel)
        runCatching { windowManager?.addView(container, params) }
            .onFailure { Log.e(TAG, "cannot add overlay", it) }
    }

    private val touchListener = View.OnTouchListener { view, event ->
        when (event.actionMasked) {
            MotionEvent.ACTION_DOWN -> {
                handler.removeCallbacks(hideTask)
                downX = event.rawX
                downY = event.rawY
                startX = params?.x ?: 0
                startY = params?.y ?: 0
                dragging = false
                scaling = false
                true
            }

            MotionEvent.ACTION_POINTER_DOWN -> {
                scaling = true
                true
            }

            MotionEvent.ACTION_MOVE -> {
                scaleDetector?.onTouchEvent(event)
                if (scaling) return@OnTouchListener true
                val dx = event.rawX - downX
                val dy = event.rawY - downY
                if (!dragging && abs(dx) + abs(dy) > TOUCH_SLOP) {
                    dragging = true
                    avatar.tilt((dx.coerceIn(-120f, 120f)) * 0.25f)
                }
                if (dragging) {
                    params?.x = startX + dx.roundToInt()
                    params?.y = startY + dy.roundToInt()
                    runCatching { windowManager?.updateViewLayout(view.root, params) }
                }
                true
            }

            MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> {
                scaleDetector?.onTouchEvent(event)
                if (dragging) {
                    avatar.tilt(0f)
                    snapToEdge()
                    savePosition()
                } else if (!scaling) {
                    onTap()
                }
                dragging = false
                scaling = false
                handler.postDelayed(hideTask, AUTO_HIDE_MS)
                true
            }

            else -> false
        }
    }

    private val scaleListener = object : ScaleGestureDetector.SimpleOnScaleGestureListener() {
        override fun onScaleBegin(detector: ScaleGestureDetector): Boolean {
            scaling = true
            return true
        }

        override fun onScale(detector: ScaleGestureDetector): Boolean {
            val target = (baseWidth * detector.scaleFactor).roundToInt()
                .coerceIn(MIN_SIZE, MAX_SIZE)
            val ratio = target.toFloat() / baseWidth
            baseHeight = (baseHeight * ratio).roundToInt()
            baseWidth = target
            params?.width = baseWidth
            params?.height = baseHeight
            runCatching { windowManager?.updateViewLayout(avatar.root, params) }
            return true
        }

        override fun onScaleEnd(detector: ScaleGestureDetector) {
            scaling = false
            prefs.avatarScale = (baseWidth.toFloat() / BASE_WIDTH).coerceIn(0.5f, 2f)
        }
    }

    private fun onTap() {
        val now = System.currentTimeMillis()
        if (now - lastTapAt < DOUBLE_TAP_MS) {
            lastTapAt = 0
            openSettings()
            return
        }
        lastTapAt = now
        avatar.pulse()
        if (VoiceChatManager.isListening() || VoiceChatManager.isSpeaking()) {
            VoiceChatManager.stop()
        } else {
            if (!VoiceChatManager.hasPermission(this)) {
                showStatus("Нужен доступ к микрофону")
                return
            }
            VoiceChatManager.start(this)
        }
    }

    private fun openSettings() {
        startActivity(
            Intent(this, SettingsActivity::class.java)
                .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        )
    }

    private fun snapToEdge() {
        val metrics = resources.displayMetrics
        val current = params ?: return
        val margin = (12 * metrics.density).roundToInt()
        val maxX = metrics.widthPixels - current.width - margin
        val maxY = metrics.heightPixels - current.height - margin
        current.x = current.x.coerceIn(margin, maxOf(margin, maxX))
        current.y = current.y.coerceIn(margin, maxOf(margin, maxY))
        if (abs(current.x - margin) < metrics.widthPixels * 0.12) current.x = margin
        if (abs(current.x - maxX) < metrics.widthPixels * 0.12) current.x = maxX
        runCatching { windowManager?.updateViewLayout(avatar.root, current) }
    }

    private fun savePosition() {
        params?.let {
            prefs.overlayX = it.x
            prefs.overlayY = it.y
        }
    }

    private fun showStatus(text: String) {
        val root = avatar.root as? android.widget.FrameLayout ?: return
        val status = root.findViewById<TextView>(R.id.overlay_status) ?: return
        status.text = text
        status.visibility = View.VISIBLE
        handler.postDelayed({ status.visibility = View.GONE }, STATUS_MS)
    }

    private fun applyPrivacy(enabled: Boolean) {
        privacy = enabled
        prefs.privacyMode = enabled
        if (enabled) {
            avatar.dim(0.75f)
            avatar.mood("sleep")
            showStatus("Приватный режим")
        } else {
            avatar.dim(0f)
            avatar.mood("idle")
        }
    }

    override fun onModelReady(model: String) {
        showStatus("Модель $model готова")
        if (privacy) avatar.mood("sleep")
    }

    override fun onModelError(message: String) {
        Log.e(TAG, "model error: $message")
        showStatus("Ошибка модели: $message")
    }

    override fun onAvatarTap(x: Float, y: Float) {
        val metrics = avatar.resources.displayMetrics
        avatar.gaze(
            ((x / metrics.density) - avatar.width / (2 * metrics.density)) /
                (avatar.width / (2f * metrics.density)),
            ((y / metrics.density) - avatar.height / (2 * metrics.density)) /
                (avatar.height / (2f * metrics.density))
        )
    }

    override fun onMood(mood: String) {
        if (privacy && mood != "sleep") return
        avatar.mood(mood)
        if (mood == "thinking") showStatus("Думаю…")
    }

    override fun onCaption(text: String) {
        avatar.caption(text)
    }

    override fun onLevel(level: Float) {
        avatar.level(level)
    }

    override fun onHeard(text: String) {
        showStatus("Ты: ${text.take(40)}")
    }

    override fun onError(message: String) {
        showStatus(message)
    }

    private fun createChannel() {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
        val manager = getSystemService(NotificationManager::class.java)
        if (manager.getNotificationChannel(CHANNEL_ID) != null) return
        val channel = NotificationChannel(
            CHANNEL_ID,
            "Аватар",
            NotificationManager.IMPORTANCE_LOW
        ).apply {
            description = "Аватар поверх других приложений"
            setShowBadge(false)
        }
        manager.createNotificationChannel(channel)
    }

    private fun startForegroundNotification() {
        val open = PendingIntent.getActivity(
            this,
            0,
            Intent(this, MainActivity::class.java),
            PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT
        )
        val stop = PendingIntent.getService(
            this,
            1,
            Intent(this, OverlayService::class.java).setAction(ACTION_STOP),
            PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT
        )
        val notification: Notification = NotificationCompat.Builder(this, CHANNEL_ID)
            .setContentTitle("Vtuber AI на экране")
            .setContentText("Тап по аватару — начать разговор")
            .setSmallIcon(R.drawable.ic_notification)
            .setOngoing(true)
            .setContentIntent(open)
            .addAction(0, "Скрыть", stop)
            .build()
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.UPSIDE_DOWN_CAKE) {
            startForeground(
                NOTIFICATION_ID,
                notification,
                ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE
            )
        } else {
            startForeground(NOTIFICATION_ID, notification)
        }
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        if (intent?.action == ACTION_STOP) {
            stopSelf()
            return START_NOT_STICKY
        }
        handler.removeCallbacks(hideTask)
        handler.postDelayed(hideTask, AUTO_HIDE_MS)
        return START_STICKY
    }

    override fun onDestroy() {
        handler.removeCallbacksAndMessages(null)
        VoiceChatManager.listener = null
        VoiceChatManager.destroy()
        runCatching { windowManager?.removeViewImmediate(avatar.root) }
        avatar.release()
        super.onDestroy()
    }

    companion object {
        private const val TAG = "OverlayService"
        private const val CHANNEL_ID = "vtuber_avatar"
        private const val NOTIFICATION_ID = 4711
        private const val ACTION_STOP = "com.vtuber.ai.action.STOP"
        private const val BASE_WIDTH = 320
        private const val BASE_HEIGHT = 400
        private const val MIN_SIZE = 180
        private const val MAX_SIZE = 900
        private const val TOUCH_SLOP = 14
        private const val DOUBLE_TAP_MS = 320L
        private const val AUTO_HIDE_MS = 120_000L
        private const val STATUS_MS = 2600L
    }
}

